//! Файл: settings/catalog/sizing.rs
//! Что делает: настройки задачи t159 (решения 342–345) — подбор объёма без потери прибыльных объёмов: порог % как
//! ограничение поиска, участки допустимости (несвязное допустимое множество), изломы пулов DEX в точки подбора, мягкий
//! срок подбора. Все необязательные: не заданы — бот считает ровно как до t159. Значений нет.
//! Отдельный файл: base.rs и cpu.rs — общие части каталога (не раздуваем).
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, раздел «Подбор объёма»).

use super::{G, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решений 342–345. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static SIZING: &[SettingDef] = &[
    d("Подбор объёма", "size.pct_constraint", K::Bool, L::None, "да/нет", G, "Решение 342 (задача t159, ошибка №20): порог прибыли в % (money.min_profit_pct направления) — ограничение подбора объёма: выбирается объём с наибольшей прибылью в USDT среди объёмов, у которых прибыль в % не ниже порога (лучший из посчитанных проходящих, его пик уточняется тернарным поиском). Без настройки — как раньше: оптимум по USDT, а % проверяется только на нём, и если там % ниже порога — кандидат отклоняется, даже когда меньший объём проходит оба порога. Пороги проверяются финальной котировкой, как всегда. Необязательна").optional(),
    d("Подбор объёма", "size.feasible_scan", K::Bool, L::None, "да/нет", G, "Решение 343 (задача t159, ошибки №18, №19): допустимые объёмы могут лежать несколькими участками — minNotional и maxNotional продажи проверяются по худшей цене (цене самого глубокого нужного уровня bids), а исполнимость сплита DEX и бюджет умного маршрута немонотонны; бисекция границ видит один отрезок. «да» — подбор считает ещё концы участков допустимости по стакану B и size.grid_points равномерных точек ниже наименьшего и выше наибольшего объёма бисекции (до удвоенной оценки по бюджету); пики среди них уточняются так же. Цена — до 2 × size.grid_points + 3 × (число участков) расчётов на кандидата сверх прежних (в пределе size.max_evals). Необязательна").optional(),
    d("Подбор объёма", "size.pool_breaks_max", K::Integer, L::Positive, "изломов на пул", G, "Решение 344 (задача t159): сколько изломов кривой каждого пула монеты отдаёт DEX в точки подбора объёма (пересечения тиков V3 / Infinity CL / Uniswap V4, границы бинов Infinity Bin / Liquidity Book, точки лесенки WooFi / Metric / iZiSwap) — к ним, как к уровням стакана биржи, добавляются точки «шаг до и после», чтобы пик прибыли между двумя точками сетки не терялся. Только память адаптера; каждая точка — полный расчёт объёма (котировка DEX), поэтому число точек растёт на 2 × изломов. Не задана — изломов DEX нет, как раньше. Необязательна").optional(),
    d("Подбор объёма", "size.soft_deadline_pct", K::Decimal, L::PercentOpen, "% срока", G, "Решение 345 (задача t159): мягкий срок подбора объёма — доля общего срока расчёта кандидата profit.calc_timeout_ms. По сроку новых точек нет, итог — лучший из посчитанных (в пояснении — «остановлен мягким сроком»), дальше финальная котировка: кандидат не теряется отказом по общему сроку, если проходящий объём уже найден. Оставьте время финальной котировке (например 70%). Не задана или не задан profit.calc_timeout_ms — как раньше. Необязательна").optional(),
];
